import requests
base = 'http://127.0.0.1:8125'
last_response = requests.get(f'{base}/batches/last', timeout=30)
last_response.raise_for_status()
last_seq = int(last_response.json()['last_seq'])
orders_response = requests.get(f'{base}/orders', params={'after': last_seq}, timeout=30)
orders_response.raise_for_status()
orders = orders_response.json()

if not orders:
    result = {'posted': False, 'last_seq': last_seq, 'order_count': 0}
else:
    required = {'seq', 'date', 'region', 'units', 'unit_price_cents'}
    invalid = [(i, sorted(required - set(order))) for i, order in enumerate(orders) if required - set(order)]
    if invalid:
        result = {'posted': False, 'last_seq': last_seq, 'order_count': len(orders), 'invalid_orders': invalid[:5]}
    else:
        revenue_by_region_cents = {}
        total_units = 0
        total_revenue_cents = 0
        for order in orders:
            units = int(order['units'])
            revenue_cents = units * int(order['unit_price_cents'])
            total_units += units
            total_revenue_cents += revenue_cents
            region = order['region']
            revenue_by_region_cents[region] = revenue_by_region_cents.get(region, 0) + revenue_cents
        batch = {
            'batch_start_seq': min(int(order['seq']) for order in orders),
            'batch_end_seq': max(int(order['seq']) for order in orders),
            'order_count': len(orders),
            'total_units': total_units,
            'total_revenue_cents': total_revenue_cents,
            'revenue_by_region_cents': revenue_by_region_cents,
        }
        post_response = requests.post(f'{base}/batches', json=batch, timeout=30)
        post_response.raise_for_status()
        result = {'posted': True, 'batch': batch, 'response_status': post_response.status_code, 'response': post_response.json() if post_response.content else None}
result

